    )

    private val collator: Collator = Collator.getInstance(Locale("fa", "IR"))

    private val byProvince: Map<String, List<String>> by lazy {
        raw.associate { (province, cities) ->
            province to cities.split("،").map { it.trim() }.filter { it.isNotEmpty() }
                .distinct().sortedWith(collator)
        }
    }

    /** نام استان‌ها به ترتیب الفبا. */
    val provinces: List<String> by lazy {
        raw.map { it.first }.sortedWith(collator)
    }

    /** شهرهای یک استان به ترتیب الفبا (بدون گزینه‌ی «شهر دیگر»). */
    fun cities(province: String): List<String> = byProvince[province].orEmpty()
}
